/* Editionskompass: shared presentation, accessibility and material adapters. */
(()=>{'use strict';
const $=s=>document.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let cfg,activeReturn;const nativePrint=window.print.bind(window);
const api=()=>window.annaPrototype||window.academy||window.raetsel||window.stadt;
const glossary=[['Git und Plattform','Git hält Dateistände und ihre Beziehungen fest. GitHub und GitLab ergänzen Hosting, Berechtigungen, Diskussionen und automatisierte Prüfabläufe.'],['Git-Repositorium, kurz Repo','Ein Repo enthält Dateien und ihre Git-Geschichte. Ein Arbeitsrepo dient der Bearbeitung; ein Publikationsrepo wird für seine Leserinnen und Leser kuratiert.'],['Commit und Übertragen','Ein Commit hält einen Änderungsschritt lokal fest. Erst das Übertragen zum entfernten Repo macht ihn auch dort verfügbar.'],['Tag, Release und Archivfassung','Ein Tag markiert einen Git-Stand. Ein Release bündelt eine bewusst freigegebene Ausgabe mit Beschreibung. Eine unabhängige Archivfassung erhält den Bestand mit Metadaten.'],['Editionsdaten, Frontend und Interface','Die wissenschaftlich verantworteten Daten tragen Texte und editorische Beziehungen. Das technische Frontend stellt ein Interface zur Erschließung der digitalen Edition bereit. Interface bezeichnet den gestalteten Zugang aus Nutzungsperspektive.'],['Prüfung und fachliche Abnahme','XML-Wohlgeformtheit, Schema-Prüfung und Funktionstests prüfen unterschiedliche Eigenschaften. Die editorische Abnahme beurteilt zusätzlich den wissenschaftlichen Inhalt. Ein grüner Test ersetzt sie nicht.'],['Durchsicht und Gutachten','Review bezeichnet hier eine vereinbarte technische oder redaktionelle Durchsicht. Ein externes wissenschaftliches Gutachten hat einen eigenen Auftrag. GitLab nennt Änderungsvorschläge Merge Requests, GitHub Pull Requests.'],['Sicherung und Betrieb','Regelmäßige Commits und Übertragung auf ein verlässlich betriebenes Uni-GitLab können Teil einer Sicherungsstrategie sein. Dateien außerhalb des Repos, Wiederherstellung, Archivierung und laufender Dienstbetrieb brauchen eigene Regelungen.']];
function details(){return glossary.map(([h,p])=>'<details><summary>'+E(h)+'</summary><p>'+E(p)+'</p></details>').join('')}
function media(root=document){$$('figure',root).forEach(f=>{const img=f.querySelector('img');if(!img)return;const rec=cfg.media.find(x=>x.file===img.getAttribute('src'));if(!rec)return;let cap=f.querySelector('figcaption');if(!cap){cap=document.createElement('figcaption');f.append(cap)}$$('.family-ai',cap).forEach(e=>e.remove());$$('span',cap).filter(e=>/KI-Illustration|KI-generiert|KI erzeugt/.test(e.textContent)).forEach(e=>e.remove());const label=document.createElement('span');label.className='family-ai';label.textContent=rec.label;cap.append(label)});}
function enhance(root=document){media(root);$$('.workflow>div',root).forEach(card=>{if(!card.querySelector('details')){const d=document.createElement('details');d.className='family-knowledge';const advice={"Bearbeiten": "Anna ergänzt an einer Briefstelle eine Lesart und ihre Begründung in der vorbereiteten TEI-Vorlage. Miras Rückfrage bleibt während der Bearbeitung als XML-Kommentar erkennbar.", "Prüfen": "Anna lässt die geänderte Datei gegen ihr Schema prüfen und öffnet die Vorschau. Sie kontrolliert gerade die bearbeitete Stelle: Wird die Lesart richtig dargestellt und ist die Fußnote am vorgesehenen Ort?", "Festhalten": "Anna vergleicht die Änderungen, speichert sie als Commit mit der Nachricht „Lesart in Brief 12 begründet“ und überträgt ihn zum privaten Uni-GitLab. Erst nach erfolgreicher Übertragung liegt dieser Stand auch dort vor.", "Veröffentlichen": "Anna erzeugt eine bereinigte Kopie für das Publikationsrepo. Sie prüft Rechte und Inhalt und entfernt interne Kommentare aus der Ausgabe. Sie überträgt nicht die private Git-Geschichte: Dort bleiben ältere Kommentare sonst lesbar.", "Lesbar machen": "Anna bietet die freigegebenen TEI-Dateien mit README und Versionsangabe zum Download an. Eine kleine Website erschließt den Text; das bezeichnete Datenpaket übergibt sie mit Metadaten an den vereinbarten Archivdienst."};const copy=Object.values(advice)[Array.from(card.parentElement.children).indexOf(card)];if(copy){d.innerHTML='<summary>Beispiel und Tipp</summary><p>'+E(copy)+'</p>';card.append(d)}}});$$('table',root).forEach(table=>{if(!table.closest('.table-scroll,.family-table-wrap')){const wrap=document.createElement('div');wrap.className='family-table-wrap';table.before(wrap);wrap.append(table)}});$$('summary',root).forEach(s=>{if(/^Beispiel\s*&\s*Tipp/.test(s.textContent))s.textContent='Beispiel und Tipp'});$$('img',root).forEach(e=>{if(!e.hasAttribute('alt'))e.alt='';});$$('svg[role="img"]',root).forEach(s=>{if(s.querySelector('[role="button"]'))s.setAttribute('role','group')});$$('details',root).forEach(e=>{if(e.closest('#print-root'))e.open=true});}
function getEntries(){if(cfg.case==='P01'){return api().getResult().entries.map(e=>({id:e.id,title:e.title,type:e.type==='c'?'chance':'risk',p:e.p==='ungeklärt'?null:e.p,w:e.w,reason:e.reason,status:e.status,git:e.detail?.git||'',action:e.action,owner:e.role,original:e.id}));}return cfg.ratings.map(r=>({...r,...cfg.riskTexts[r.id],type:r.type}));}
function field(v){return v==='hoch'||v==='höher'||v==='weitreichend'?1:0}
function matrixHTML(entries){return ['chance','risk'].map(type=>{const cells=[1,0].map(w=>[0,1].map(p=>{const items=entries.filter(e=>e.type===type&&e.p&&!e.status&&field(e.p)===p&&field(e.w)===w);return '<div class="family-quadrant" role="group" aria-label="Wirkung '+(w?'weitreichend':'begrenzt')+', Plausibilität '+(p?'höher':'geringer')+'">'+(items.map(e=>'<button class="family-chip" data-family-entry="'+E(e.id)+'" data-type="'+type+'" aria-haspopup="dialog" aria-label="'+E(e.title+'; Plausibilität '+e.p+'; Wirkung '+e.w)+'">'+E(e.title)+'</button>').join('')||'<span class="family-empty">Kein Thema eingeordnet</span>')+'</div>'}).join('')).join('');return '<article class="family-matrix"><h4>'+(type==='chance'?'Chancen':'Risiken')+'</h4><div class="family-matrix-layout"><span class="family-y">Wirkung ↑</span><span class="family-y-high">weitreichend</span><span class="family-y-low">begrenzt</span><div class="family-quadrants">'+cells+'</div><span class="family-x-low">geringer</span><span class="family-x-high">höher</span><span class="family-x">Plausibilität →</span></div></article>'}).join('')}
function entryTable(entries){return '<div class="family-table-wrap"><table class="family-table"><caption>Einordnungen und nächste Schritte</caption><thead><tr><th scope="col">Thema</th><th scope="col">Art</th><th scope="col">Plausibilität / Wirkung</th><th scope="col">Begründung und Handlung</th></tr></thead><tbody>'+entries.map(e=>'<tr><th scope="row">'+E(e.title)+'</th><td>'+E(e.type==='chance'?'Chance':'Risiko')+'</td><td>'+E(e.status||((e.p||'ungeklärt')+' / '+e.w))+'</td><td>'+E(e.reason)+'<br><strong>Handlung:</strong> '+E(e.action)+'<br><strong>Zuständig:</strong> '+E(e.owner)+'</td></tr>').join('')+'</tbody></table></div>'}
function updateMatrix(){const root=$('#family-matrix');if(!root)return;const entries=getEntries();root.querySelector('.family-matrix-pair').innerHTML=matrixHTML(entries);root.querySelector('.family-unknown').innerHTML=entries.filter(e=>!e.p||e.status).map(e=>'<button class="family-chip" data-family-entry="'+E(e.id)+'" data-type="'+e.type+'" aria-haspopup="dialog">'+E(e.title)+' · '+E(e.status||'Plausibilität ungeklärt')+'</button>').join(' ');root.querySelector('.family-full-ratings').innerHTML=entryTable(entries);}
function openEntry(id,trigger){if(cfg.case==='P01'){const e=api().getResult().entries.find(e=>e.id===id);const original=$$('[data-open-entry]').find(b=>b.dataset.openEntry===id);if(original){original.click();const dialog=$$('dialog').find(d=>d.open);dialog?.addEventListener('close',()=>trigger.focus(),{once:true});return}}
const e=getEntries().find(e=>e.id===id);if(!e)return;activeReturn=trigger;const box=$('#family-dialog');$('#family-dialog-body').innerHTML='<p class="family-eyebrow">'+(e.type==='chance'?'Chance':'Risiko')+'</p><h2 id="family-dialog-title">'+E(e.title)+'</h2><p>'+E(e.situation)+'</p><div class="family-rating"><strong>Plausibilität: '+E(e.p||'ungeklärt')+' · Wirkung: '+E(e.w)+'</strong><p>'+E(e.reason)+'</p></div><h3>Wie hilft Git?</h3><p>'+E(e.git)+'</p><h3>Was gibt es zu bedenken?</h3><p>'+E(e.consider)+'</p><h3>Handlung</h3><p>'+E(e.action)+'</p><p><strong>Zuständig:</strong> '+E(e.owner)+'</p>';box.showModal();box.querySelector('button').focus();}
function graphText(root){$$('svg',root).forEach(svg=>{if(svg.closest('.family-table-wrap'))return;const labels=$$('text',svg).map(e=>e.textContent.trim()).filter(Boolean);const d=document.createElement('details');d.className='family-graph-text';d.innerHTML='<summary>Grafik als Text lesen</summary><p>'+E(svg.querySelector('title')?.textContent||svg.getAttribute('aria-label')||'Zusammenhang der dargestellten Schritte')+'</p><ol>'+[...new Set(labels)].map(x=>'<li>'+E(x)+'</li>').join('')+'</ol>';svg.after(d);});}
async function prepare(kind,reading=true){const root=$('#print-root');window.print=()=>{};try{if(kind==='family-strategy')root.innerHTML='<h1>Unsere Musterstrategie</h1><ol>'+cfg.strategy.map(t=>'<li>'+E(t)+'</li>').join('')+'</ol><h2>Begriffe für den Arbeitsweg</h2>'+details();
else if(kind==='family-risks')root.innerHTML='<h1>Chancen, Risiken und Gegenmaßnahmen</h1><p>'+E(cfg.ratingBasis)+'</p>'+getEntries().map(e=>'<section class="family-risk-sheet"><h2>'+E(e.title)+'</h2><p><strong>'+(e.type==='chance'?'Chance':'Risiko')+' · Plausibilität '+E(e.p||'ungeklärt')+' · Wirkung '+E(e.w)+'</strong></p><p>'+E(e.reason)+'</p><p><strong>Wie hilft Git?</strong> '+E(e.git)+'</p><p><strong>Handlung:</strong> '+E(e.action)+'</p><p><strong>Zuständig:</strong> '+E(e.owner)+'</p></section>').join('');
else if(kind==='family-rules')root.innerHTML='<h1>Arbeitsregeln</h1>'+cfg.rules.map(x=>'<h2>'+E(x[0])+'</h2><p>'+E(x[1])+'</p>').join('');
else if(kind==='family-architecture'){root.innerHTML='<h1>Arbeits- und Publikationsarchitektur</h1>';for(const s of cfg.architectureSelectors){const e=$(s);if(e)root.append(e.cloneNode(true));}if(!root.querySelector('p,svg,img'))root.innerHTML+='<ol>'+cfg.strategy.map(x=>'<li>'+E(x)+'</li>').join('')+'</ol>';}
else if(kind==='family-cascade'){root.innerHTML='<h1>Eine Ursache, mehrere Folgen</h1>'+'<img src="assets/anna-folgekette.svg" alt="Ende der Universitätsanbindung und seine gekoppelten Folgen"/><p>Endet die Universitätsanbindung, prüfen wir Repo-Zugang, Werkzeuglizenz, Beratung und Publikationsdienste einzeln. Ein Repo-Umzug erhält Dateien und Git-Geschichte, ersetzt aber weder Beratung noch eine Werkzeuglizenz. Die Maßnahmen laufen bei der geplanten Weiterarbeit zusammen.</p>';}else if(kind==='family-stories'){root.innerHTML='<h1>Situationen · Lesefassung</h1>';for(const s of cfg.storySelectors)$$(s).forEach(e=>root.append(e.cloneNode(true)));}
else await api().printMaterial(kind,false);
}finally{window.print=nativePrint}
root.querySelectorAll('.meta,.print-meta').forEach(e=>e.remove());for(const image of root.querySelectorAll('img[src$=".svg"]')){const response=await fetch(image.getAttribute('src'));if(response.ok){const holder=document.createElement('div');holder.innerHTML=await response.text();const svg=holder.querySelector('svg');if(svg){svg.classList.add('diagram');image.replaceWith(svg)}}}if(['graph','decisions','family-architecture'].includes(kind)){const explanation=document.querySelector('#erkunden>.family-graph-text');if(explanation)root.append(explanation.cloneNode(true));}root.querySelectorAll('dialog,script,button,select,input,nav,.family-screen-only').forEach(e=>e.remove());$$('[id]',root).forEach(e=>{if(e.id!=='print-root')e.removeAttribute('id')});$$('[role=button]',root).forEach(e=>{e.removeAttribute('tabindex');e.setAttribute('role','group')});root.prepend(Object.assign(document.createElement('p'),{className:'family-material-meta',textContent:'Editionskompass · '+cfg.label+' · Gemeinsamer Stand 1.1 · 27. Oktober 2026 · '+(kind==='strategy'?'Aktuelle Auswahl':'Material')}));enhance(root);graphText(root);$$('details',root).forEach(d=>d.open=true);if(!root.querySelector('h1'))root.insertAdjacentHTML('afterbegin','<h1>'+E(cfg.materials.find(m=>m.kind===kind)?.title||'Material')+'</h1>');
{let st=$('#family-page-size');if(!st){st=document.createElement('style');st.id='family-page-size';document.head.append(st)}st.textContent='@page{size:'+(kind==='graph'||kind==='decisions'?'A3':'A4')+' portrait;margin:16mm}'}
root.querySelectorAll('img').forEach(img=>{if(!img.alt)img.alt=img.closest('figure')?.querySelector('figcaption')?.textContent||'Lehrgrafik zum beschriebenen Arbeitsweg'});await Promise.all($$('img',root).map(e=>e.decode().catch(()=>{})));
if(reading){document.body.classList.add('family-reading');const bar=document.createElement('div');bar.className='family-toolbar';bar.innerHTML='<a href="'+E(location.pathname)+'">Zurück zum Fall</a><button type="button" id="family-read-print">Drucken</button><button type="button" id="family-read-source">Als HTML speichern</button>';root.prepend(bar);$('#family-read-print').onclick=()=>nativePrint();$('#family-read-source').onclick=()=>saveHTML(kind);root.tabIndex=-1;root.focus();window.scrollTo(0,0)}return root;}
function saveHTML(kind){const text='<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>'+E(cfg.label)+' · Material</title><style>body{max-width:900px;margin:40px auto;padding:0 20px;font:18px/1.7 Arial,sans-serif}svg,img{max-width:100%;height:auto}table{border-collapse:collapse}th,td{border:1px solid #777;padding:10px;vertical-align:top}pre{white-space:pre-wrap}a,button{padding:8px}.family-toolbar{display:none}</style><body>'+$('#print-root').innerHTML+'</body></html>';const u=URL.createObjectURL(new Blob([text],{type:'text/html;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=cfg.case+'-'+kind+'.html';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function materials(){const target=$(cfg.materialTarget);if(!target)return;const head=target.querySelector('h2');if(head)head.innerHTML='Materialien.<br>Mitnehmen und anwenden.';const grid=document.createElement('div');grid.className='family-materials';grid.innerHTML=cfg.materials.map(m=>'<article class="family-material"><h3>'+E(m.title)+'</h3><p>'+E(m.description)+' · '+E(m.format||'A4')+'</p><div class="family-actions"><a href="assets/'+E(m.pdf.replace('.pdf','.html'))+'">HTML lesen</a><a href="assets/'+E(m.pdf)+'" download>PDF herunterladen</a><button type="button" data-family-print="'+E(m.kind)+'">Drucken</button><a href="assets/'+E(m.pdf.replace('.pdf','.html'))+'" download>Bearbeitbare Vorlage</a></div></article>').join('');const old=target.querySelector('.materials-grid,#materials,.material-grid,.cards');if(old){old.querySelectorAll('.material,[data-print]').forEach(e=>{const kind=e.dataset.print||e.querySelector('[data-print]')?.dataset.print;if(cfg.hideOriginal.includes(kind))e.closest('.material,article,button')?.remove()});old.before(grid);if(old.children.length){old.before(Object.assign(document.createElement('h3'),{textContent:'Weitere Materialien'}))}}else{const heading=target.querySelector('h2');const parent=heading.closest('.section-heading')||heading;if(parent)parent.after(grid);else target.prepend(grid)}}
function setupDialogs(){document.querySelectorAll('a[href$=".pdf"]').forEach(a=>{if(a.closest('.family-material'))return;let kind=a.getAttribute('href').split('/').pop().replace('.pdf','');if(cfg.case==='P01')kind=kind.includes('architektur')?'family-architecture':kind.includes('folgekette')?'family-cascade':'graph';const link=document.createElement('a');link.href=a.getAttribute('href').replace('.pdf','.html');link.className='family-screen-only';link.textContent=' HTML lesen';a.after(link)});const d=document.createElement('dialog');d.id='family-dialog';d.className='family-dialog';d.setAttribute('aria-labelledby','family-dialog-title');d.innerHTML='<button class="family-dialog-close" type="button">Schließen</button><div id="family-dialog-body"></div>';document.body.append(d);d.querySelector('button').onclick=()=>d.close();d.addEventListener('close',()=>{if(activeReturn?.isConnected)activeReturn.focus()});document.addEventListener('click',e=>{const b=e.target.closest('[data-family-entry]');if(b)openEntry(b.dataset.familyEntry,b);const p=e.target.closest('[data-family-print]');if(p)prepare(p.dataset.familyPrint,false).then(()=>nativePrint());});let ret;document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(b&&!b.closest('dialog'))ret=b},true);$$('dialog').forEach(d=>{d.addEventListener('close',()=>{if(ret?.isConnected)ret.focus()});});}
async function init(){cfg=await(await fetch('familie.json')).json();for(let n=0;n<300&&!api();n++)await new Promise(r=>setTimeout(r,100));if(!api())throw Error('Fall konnte nicht initialisiert werden');window.editionsFamily={prepare,config:cfg,updateMatrix};document.querySelector("#family-glossary").innerHTML=details();enhance();(cfg.practice||[]).forEach(p=>{const target=document.querySelector(p.target);if(target&&!target.querySelector('.family-steps')){const block=document.createElement('aside');block.className='family-steps';block.innerHTML='<h4>Merken</h4><p>'+E(p.takeaway)+'</p><h4>Nächste Schritte</h4><ol><li>'+E(p.action)+'</li><li>Prüfstand, fachliche und technische Prüfung nachvollziehbar festhalten.</li><li>Entscheidung und Zuständigkeit in die geltenden Regeln übernehmen.</li></ol><p><strong>Erledigt, wenn:</strong> '+E(p.done)+'</p>';target.append(block)}});materials();setupDialogs();updateMatrix();const live=document.createElement('p');live.id='family-choice-status';live.setAttribute('role','status');live.className='family-notice';document.querySelector('#erkunden').append(live);let timer;document.addEventListener('change',()=>{clearTimeout(timer);timer=setTimeout(()=>{updateMatrix();enhance();document.querySelector('#family-choice-status').textContent='Auswahl aktualisiert. Die Folgen stehen bei den gewählten Voraussetzungen.';},80)});document.addEventListener('click',e=>{if(e.target.closest('[data-event],#reset,[data-key],[data-graph-key]')){clearTimeout(timer);timer=setTimeout(()=>{updateMatrix();enhance();document.querySelector('#family-choice-status').textContent='Auswahl aktualisiert. Die Folgen stehen bei den gewählten Voraussetzungen.';},80)}});$$('.reset-button,#reset-scenario,#reset').forEach(b=>b.textContent='Zur Ausgangslage zurück');$$('.graph-details svg,[id*=graph] svg').forEach(e=>{if(e.querySelector('[role=button]'))e.setAttribute('role','group')});const kind=new URLSearchParams(location.search).get('material');if(kind){await prepare(kind);if(new URLSearchParams(location.search).has('source')){const note=document.createElement('p');note.textContent='Die bearbeitbare HTML-Vorlage können Sie über „Als HTML speichern“ herunterladen und lokal öffnen.';$('#print-root .family-toolbar').after(note)}}}
init().catch(e=>{console.error(e);const status=$('#family-load-status');if(status)status.textContent='Die gemeinsamen Elemente konnten nicht geladen werden. Die Fallinhalte und bisherigen Materialien bleiben erreichbar.'});
})();

